      SUBROUTINE FNDELM(KNAME,NPARM,TYPES)CC---- DEAL WITH PARAMETER, MARKER, OR STORE NAMELISTC      CHARACTER*15      KNAME      INTEGER           NPARM, TYPESCC----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'C-----------------------------------------------------------------------      INTEGER         TYPENC-----------------------------------------------------------------------C-----------------------------------------------------------------------      NPARM = 0      DO 100 NN = 1, NEL      NNN = NN                      	      II = ISTOR(NN)      TYPEN = IDATA(II)      IF (TYPEN .NE. TYPES) GO TO 100      IF (KNAME .EQ. LABEL(NN)) GO TO 110  100 CONTINUE      GO TO 120C  110 NPARM = NNNC  120 CONTINUE      RETURNC-----------------------------------------------------------------------      END